cat >> test/app.test.ts <<'EOF'

test("POST /orders places an order, charges once and reduces stock", async () => {
  const before = (await (await fetch(`${base}/products`, { headers: as("alice-token") })).json()) as { id: number; stock: number; price_cents: number }[];
  const p = before[0];
  const res = await fetch(`${base}/orders`, {
    method: "POST",
    headers: { ...as("alice-token"), "content-type": "application/json" },
    body: JSON.stringify({ items: [{ productId: p.id, quantity: 2 }] }),
  });
  assert.equal(res.status, 201);
  const order = await res.json();
  assert.equal(order.status, "paid");
  assert.equal(order.total_cents, p.price_cents * 2);
  const after = (await (await fetch(`${base}/products`, { headers: as("alice-token") })).json()) as { id: number; stock: number }[];
  assert.equal(after.find((x) => x.id === p.id)!.stock, p.stock - 2);
});

test("POST /orders rejects insufficient stock without changing it", async () => {
  const res = await fetch(`${base}/orders`, {
    method: "POST",
    headers: { ...as("alice-token"), "content-type": "application/json" },
    body: JSON.stringify({ items: [{ productId: 1, quantity: 100000 }] }),
  });
  assert.equal(res.status, 409);
  assert.equal((await res.json()).error.code, "insufficient_stock");
});

test("POST /orders validates the body", async () => {
  const res = await fetch(`${base}/orders`, {
    method: "POST",
    headers: { ...as("alice-token"), "content-type": "application/json" },
    body: JSON.stringify({ items: [{ productId: 1, quantity: 0 }] }),
  });
  assert.equal(res.status, 400);
});
EOF
